def rows() -> list[dict]:
    out = [{"type": "mc", "text": t, "question": q, "options": o, "answer": o[0]} for t, q, o in MC]
    out += [{"type": "tf", "text": t, "question": q, "options": ["Правда", "Неправда"],
             "answer": "Правда" if a else "Неправда"} for t, q, a in TF]
    return out


if __name__ == "__main__":
    import random
    f = ROOT / "data" / "quiz" / "quiz.jsonl"
    old = [json.loads(x) for x in f.read_text(encoding="utf-8").splitlines() if x.strip()]
    for r in old:
        r.setdefault("type", "mc")
    have = {r["text"] for r in old}
    new = [r for r in rows() if r["text"] not in have]
    rnd = random.Random(42)
    for r in new:  # правильна відповідь не завжди першою
        if r["type"] == "mc":
            rnd.shuffle(r["options"])
    allr = old + new
    f.write_text("\n".join(json.dumps(r, ensure_ascii=False) for r in allr) + "\n", encoding="utf-8")
    print(len(old), "+", len(new), "=", len(allr))
